cat > example/main.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"os"
	"strings"

	"argparse"
)

func main() {
	p := argparse.New("greet", "Print a greeting.")
	loud := p.Bool("loud", 'l', "shout the greeting")
	count := p.Int("count", 'c', 1, "number of times to greet")
	greeting := p.String("greeting", 'g', "Hello", "greeting word to use")
	name := p.Arg("name", "who to greet")
	others := p.Rest("others", "more people to greet")

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, argparse.ErrHelp) {
			fmt.Print(p.Usage())
			return
		}
		fmt.Fprintf(os.Stderr, "greet: %v\n\n%s", err, p.Usage())
		os.Exit(2)
	}

	for _, who := range append([]string{*name}, *others...) {
		line := fmt.Sprintf("%s, %s!", *greeting, who)
		if *loud {
			line = strings.ToUpper(line)
		}
		for i := 0; i < *count; i++ {
			fmt.Println(line)
		}
	}
}
