package argparse

import (
	"errors"
	"reflect"
	"strings"
	"testing"
)

type result struct {
	verbose, all bool
	count        int
	out          string
	src          string
	rest         []string
}

func parse(args ...string) (result, error) {
	p := New("prog", "Does things.")
	verbose := p.Bool("verbose", 'v', "be chatty")
	all := p.Bool("all", 'a', "include everything")
	count := p.Int("count", 'c', 1, "how many")
	out := p.String("out", 'o', "", "output file")
	src := p.Arg("src", "source file")
	rest := p.Rest("extra", "extra files")
	err := p.Parse(args)
	return result{*verbose, *all, *count, *out, *src, *rest}, err
}

func TestParse(t *testing.T) {
	tests := []struct {
		args []string
		want result
	}{
		{[]string{"in"}, result{count: 1, src: "in"}},
		{[]string{"--verbose", "in"}, result{verbose: true, count: 1, src: "in"}},
		{[]string{"in", "-v"}, result{verbose: true, count: 1, src: "in"}},
		{[]string{"--verbose=false", "in"}, result{count: 1, src: "in"}},
		{[]string{"--count", "3", "in"}, result{count: 3, src: "in"}},
		{[]string{"--count=3", "in"}, result{count: 3, src: "in"}},
		{[]string{"-c", "-3", "in"}, result{count: -3, src: "in"}},
		{[]string{"-c3", "in"}, result{count: 3, src: "in"}},
		{[]string{"-c=3", "in"}, result{count: 3, src: "in"}},
		{[]string{"-va", "in"}, result{verbose: true, all: true, count: 1, src: "in"}},
		{[]string{"-vao", "f.txt", "in"}, result{verbose: true, all: true, count: 1, out: "f.txt", src: "in"}},
		{[]string{"-vof.txt", "in"}, result{verbose: true, count: 1, out: "f.txt", src: "in"}},
		{[]string{"--out=", "in"}, result{count: 1, src: "in"}},
		{[]string{"--out", "a=b", "in"}, result{count: 1, out: "a=b", src: "in"}},
		{[]string{"in", "x", "y"}, result{count: 1, src: "in", rest: []string{"x", "y"}}},
		{[]string{"-", "x"}, result{count: 1, src: "-", rest: []string{"x"}}},
		{[]string{"--", "-v", "--out"}, result{count: 1, src: "-v", rest: []string{"--out"}}},
		{[]string{"in", "--", "-v"}, result{count: 1, src: "in", rest: []string{"-v"}}},
	}
	for _, tt := range tests {
		got, err := parse(tt.args...)
		if err != nil {
			t.Errorf("%q: unexpected error: %v", tt.args, err)
			continue
		}
		if len(got.rest) == 0 {
			got.rest = nil
		}
		if !reflect.DeepEqual(got, tt.want) {
			t.Errorf("%q:\n got %+v\nwant %+v", tt.args, got, tt.want)
		}
	}
}

func TestParseErrors(t *testing.T) {
	tests := []struct {
		args []string
		want string
	}{
		{[]string{}, "missing argument <src>"},
		{[]string{"--nope", "in"}, "unknown flag --nope"},
		{[]string{"-x", "in"}, "unknown flag -x"},
		{[]string{"-vx", "in"}, "unknown flag -x"},
		{[]string{"in", "--count"}, "flag --count requires a value"},
		{[]string{"in", "-c"}, "flag -c requires a value"},
		{[]string{"--count=abc", "in"}, `flag --count: expected an integer, got "abc"`},
		{[]string{"--verbose=maybe", "in"}, `flag --verbose: expected true or false, got "maybe"`},
	}
	for _, tt := range tests {
		_, err := parse(tt.args...)
		if err == nil || err.Error() != tt.want {
			t.Errorf("%q: got error %v, want %q", tt.args, err, tt.want)
		}
	}
}

func TestExtraPositional(t *testing.T) {
	p := New("prog", "")
	p.Arg("src", "source file")
	err := p.Parse([]string{"a", "b"})
	if err == nil || err.Error() != `unexpected argument "b"` {
		t.Errorf("got error %v", err)
	}
}

func TestHelp(t *testing.T) {
	for _, args := range [][]string{{"-h"}, {"--help"}, {"-vh"}, {"in", "--help"}} {
		if _, err := parse(args...); !errors.Is(err, ErrHelp) {
			t.Errorf("%q: got %v, want ErrHelp", args, err)
		}
	}
	if _, err := parse("--", "--help"); err != nil {
		t.Errorf("--help after -- should be positional, got %v", err)
	}
}

func TestUsage(t *testing.T) {
	p := New("prog", "Does things.")
	p.Bool("verbose", 'v', "be chatty")
	p.Bool("dry-run", 0, "change nothing")
	p.Int("count", 'c', 1, "how many")
	p.String("out", 'o', "a.txt", "output file")
	p.Arg("src", "source file")
	p.Rest("extra", "extra files")

	want := strings.TrimLeft(`
Usage: prog [options] <src> [extra...]

Does things.

Arguments:
  src    source file
  extra  extra files

Options:
  -h, --help          show this help
  -v, --verbose       be chatty
      --dry-run       change nothing
  -c, --count <int>   how many (default 1)
  -o, --out <string>  output file (default "a.txt")
`, "\n")
	if got := p.Usage(); got != want {
		t.Errorf("got:\n%s\nwant:\n%s", got, want)
	}
}
