package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name    string
	short   rune   // 0 if the flag has no short form
	help    string
	kind    string // value placeholder shown in help; "" for boolean flags
	defText string // default shown in help; "" to omit
	set     func(string) error
}

func (f *flag) isBool() bool { return f.kind == "" }

type positional struct {
	name string
	help string
	dest *string
}

// Parser holds a set of flag and positional argument definitions.
type Parser struct {
	name string
	desc string

	flags []*flag
	long  map[string]*flag
	short map[rune]*flag

	args     []positional
	restName string
	restHelp string
	rest     *[]string
}

// New returns a parser for a program with the given name and description.
// The description may be empty.
func New(name, description string) *Parser {
	p := &Parser{
		name:  name,
		desc:  description,
		long:  map[string]*flag{},
		short: map[rune]*flag{},
	}
	p.add(&flag{name: "help", short: 'h', help: "show this help"})
	return p
}

func (p *Parser) add(f *flag) {
	if f.name == "" || strings.HasPrefix(f.name, "-") || strings.ContainsAny(f.name, "= ") {
		panic(fmt.Sprintf("argparse: invalid flag name %q", f.name))
	}
	if _, dup := p.long[f.name]; dup {
		panic(fmt.Sprintf("argparse: flag --%s defined twice", f.name))
	}
	p.long[f.name] = f
	if f.short != 0 {
		if f.short == '-' || f.short == '=' {
			panic(fmt.Sprintf("argparse: invalid short flag %q", f.short))
		}
		if _, dup := p.short[f.short]; dup {
			panic(fmt.Sprintf("argparse: flag -%c defined twice", f.short))
		}
		p.short[f.short] = f
	}
	p.flags = append(p.flags, f)
}

// Bool defines a boolean flag, false by default. It is set with --name or
// -s, and accepts an explicit value as --name=false. Pass 0 as short for a
// flag with no short form.
func (p *Parser) Bool(name string, short rune, help string) *bool {
	v := new(bool)
	p.add(&flag{name: name, short: short, help: help, set: func(s string) error {
		b, err := strconv.ParseBool(s)
		if err != nil {
			return fmt.Errorf("expected true or false, got %q", s)
		}
		*v = b
		return nil
	}})
	return v
}

// String defines a flag that takes a string value.
func (p *Parser) String(name string, short rune, def, help string) *string {
	v := new(string)
	*v = def
	f := &flag{name: name, short: short, help: help, kind: "string", set: func(s string) error {
		*v = s
		return nil
	}}
	if def != "" {
		f.defText = strconv.Quote(def)
	}
	p.add(f)
	return v
}

// Int defines a flag that takes an integer value.
func (p *Parser) Int(name string, short rune, def int, help string) *int {
	v := new(int)
	*v = def
	f := &flag{name: name, short: short, help: help, kind: "int", set: func(s string) error {
		n, err := strconv.Atoi(s)
		if err != nil {
			return fmt.Errorf("expected an integer, got %q", s)
		}
		*v = n
		return nil
	}}
	if def != 0 {
		f.defText = strconv.Itoa(def)
	}
	p.add(f)
	return v
}

// Arg defines a required positional argument. Positional arguments are
// filled in the order they are defined.
func (p *Parser) Arg(name, help string) *string {
	v := new(string)
	p.args = append(p.args, positional{name: name, help: help, dest: v})
	return v
}

// Rest collects any positional arguments left over after those defined with
// Arg. Without it, extra positional arguments are an error.
func (p *Parser) Rest(name, help string) *[]string {
	if p.rest != nil {
		panic("argparse: Rest defined twice")
	}
	p.restName, p.restHelp = name, help
	p.rest = new([]string)
	return p.rest
}

// Parse parses args, which should not include the program name (pass
// os.Args[1:]). It returns ErrHelp if help was requested.
//
// Flags and positional arguments may be mixed. A value is given as
// --name=value, --name value, -n value or -nvalue, and short boolean flags
// can be combined as -abc. Everything after a bare "--" is positional.
func (p *Parser) Parse(args []string) error {
	var pos []string

	for i := 0; i < len(args); i++ {
		arg := args[i]

		switch {
		case arg == "--":
			pos = append(pos, args[i+1:]...)
			i = len(args)

		case strings.HasPrefix(arg, "--"):
			name, value, hasValue := strings.Cut(arg[2:], "=")
			f, ok := p.long[name]
			if !ok {
				return fmt.Errorf("unknown flag --%s", name)
			}
			if f.name == "help" {
				return ErrHelp
			}
			if !hasValue {
				if f.isBool() {
					value = "true"
				} else {
					if i+1 >= len(args) {
						return fmt.Errorf("flag --%s requires a value", name)
					}
					i++
					value = args[i]
				}
			}
			if err := f.set(value); err != nil {
				return fmt.Errorf("flag --%s: %v", name, err)
			}

		case strings.HasPrefix(arg, "-") && arg != "-":
			// One or more short flags: -v, -abc, -n value, -nvalue, -n=value.
			group := arg[1:]
			for len(group) > 0 {
				r, size := utf8.DecodeRuneInString(group)
				group = group[size:]
				f, ok := p.short[r]
				if !ok {
					return fmt.Errorf("unknown flag -%c", r)
				}
				if f.name == "help" {
					return ErrHelp
				}
				value := "true"
				if strings.HasPrefix(group, "=") {
					value, group = group[1:], ""
				} else if !f.isBool() {
					if group != "" {
						value, group = group, ""
					} else {
						if i+1 >= len(args) {
							return fmt.Errorf("flag -%c requires a value", r)
						}
						i++
						value = args[i]
					}
				}
				if err := f.set(value); err != nil {
					return fmt.Errorf("flag -%c: %v", r, err)
				}
			}

		default:
			pos = append(pos, arg)
		}
	}

	if len(pos) < len(p.args) {
		return fmt.Errorf("missing argument <%s>", p.args[len(pos)].name)
	}
	for i, a := range p.args {
		*a.dest = pos[i]
	}
	extra := pos[len(p.args):]
	if p.rest != nil {
		*p.rest = extra
	} else if len(extra) > 0 {
		return fmt.Errorf("unexpected argument %q", extra[0])
	}
	return nil
}

// Usage returns the help message generated from the definitions.
func (p *Parser) Usage() string {
	var b strings.Builder

	fmt.Fprintf(&b, "Usage: %s [options]", p.name)
	for _, a := range p.args {
		fmt.Fprintf(&b, " <%s>", a.name)
	}
	if p.rest != nil {
		fmt.Fprintf(&b, " [%s...]", p.restName)
	}
	b.WriteString("\n")

	if p.desc != "" {
		fmt.Fprintf(&b, "\n%s\n", p.desc)
	}

	if len(p.args) > 0 || p.rest != nil {
		var rows [][2]string
		for _, a := range p.args {
			rows = append(rows, [2]string{a.name, a.help})
		}
		if p.rest != nil {
			rows = append(rows, [2]string{p.restName, p.restHelp})
		}
		b.WriteString("\nArguments:\n")
		writeRows(&b, rows)
	}

	var rows [][2]string
	for _, f := range p.flags {
		left := "    "
		if f.short != 0 {
			left = fmt.Sprintf("-%c, ", f.short)
		}
		left += "--" + f.name
		if !f.isBool() {
			left += " <" + f.kind + ">"
		}
		right := f.help
		if f.defText != "" {
			right += " (default " + f.defText + ")"
		}
		rows = append(rows, [2]string{left, right})
	}
	b.WriteString("\nOptions:\n")
	writeRows(&b, rows)

	return b.String()
}

// writeRows writes two-column rows with the second column aligned.
func writeRows(b *strings.Builder, rows [][2]string) {
	width := 0
	for _, r := range rows {
		if n := utf8.RuneCountInString(r[0]); n > width {
